pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead: next item fits here; reward tighter gaps
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
            score += 1.2;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space
        let dead = post_residual as f64;
        score += 3.2 + 0.02 * dead;
        if dead > 0.0 {
            score += 42.0 * (1.0 - dead / cap_f);
        }
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual > 0 && post_residual < bin_capacity / 12 {
            score += 2.2;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score += 1.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 500.0;
    }

    // Penalize fragmentation relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if fitting_bins_count > 0 {
            let slack = pr / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 1.5;
        }
        // Fresh bin preferable if next item is large relative to post-fit residual
        if next_item_size > post_residual + item_size.min(bin_capacity) {
            score -= 50.0;
        }
    }

    // Mild consolidation pressure as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny useless residuals
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Exact fit of item into residual (near-perfect fill).
    if item_size == bin_residual {
        score -= 10.5;
    } else if item_size >= bin_residual {
        score -= 2.0;
    }

    // 2-step lookahead: reward when next item fits the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Tighter coupling: reward small gaps more aggressively.
        score -= 50.0 * (1.0 - gap / cap_f);
        if gap < 8.0 {
            score -= 2.0 * (1.0 - gap / 8.0);
        }
        if gap < 4.0 {
            score -= 0.8 * (1.0 - gap / 4.0);
        }
        // Gap can host the next item again: keep bin attractive.
        if gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.2;
            }
        }
        // Gap large enough to host next item twice: excellent reuse potential.
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.5;
        }
        // Gap smaller than mean residual: keeps global balance.
        if (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 40.0 + 60.0 * (1.0 - dead / cap_f);
            if dead < 20.0 {
                score += 2.0;
            }
            if dead < cap_f / 10.0 {
                score += 2.0;
            }
            // Proportional dead-space penalty relative to what next item needs.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless residuals are large/fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        // If next item is small and no good fit exists, opening a fresh bin is fine.
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 1.0;
        }
        // Avoid opening bins when a future large item would benefit from a residual.
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.6;
        }
        // Opening a bin is acceptable when current item leaves room for the next one.
        if next_item_size > 0 && item_size + 12 <= bin_residual && item_size + 12 < next_item_size {
            score -= 2.2;
        }
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items (more bins to work with later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // Next item can chain-fill this residual twice: extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    score
}

