        }
        score += 0.5 * open_bins_count as f64;
    }

    // Mild consolidation pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny dead space
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}

