pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact item fit (item closes bin) - very strong reward.
    if item_size == bin_residual {
        score -= 12.0;
    }

    // 2-step lookahead: reward when next item exactly fills the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.5 + 4.5 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 6.5;
        }
        if gap > 0.0 && (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
        if gap > 0.0 && gap >= next_item_size as f64 {
            score -= 2.5;
        }
        if gap > 0.0 && (gap as u32) >= next_item_size {
            score -= 1.5 * (1.0 - gap / post_residual as f64);
        }
        if gap > 0.0 && gap >= next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 1.2;
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 1.0 * (1.0 - gap / 8.0);
        }
        if gap as u32 >= 2 * next_item_size {
            score -= 1.5;
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 0.8 * (1.0 - gap / 4.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        score += 3.2 + 0.02 * post_residual as f64;
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
            score += 1.0;
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.01 * cap_f + 0.004 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 0.8;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + 12 <= bin_residual && item_size + 12 < next_item_size {
            score -= 2.2;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.6;
        }
        // Allow new bin when open bins are highly fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Small dead-space traps: leftovers too small for next item.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.05;
    }
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 1.0;
    }
    if post_residual > 0 && post_residual < next_item_size && post_residual < bin_capacity / 10 {
        score += 2.0;
    }

    // Next item fits and residual stays within 2x next item with many alternatives.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
