    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "reusable" classes
    // (multiples of 10, or >= 50) are rewarded; tiny dead-space leftovers are penalized.
    let post = post_residual;
    let class_mod = post % 10;
    if post > 0 {
        if class_mod == 0 {
            score -= 8.0; // perfectly reusable leftover
        } else if class_mod <= 3 {
            score += 6.0; // nearly dead space
        }
        // capacity-fraction coupling
        let frac = post as f64 / cap;
        if frac >= 0.5 {
            score -= 5.0; // large leftover is flexible
        } else if frac <= 0.1 {
            score += 7.0; // unusable sliver
        }
    }

    // Integer-division threshold: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 4.0; // lookahead item can use this bin next
        } else {
            score += (next_item_size - post) as f64 * 0.15;
        }
        // Harmonic match: next item and leftover share a divisor class
        if post > 0 && next_item_size % 10 == post % 10 && post >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Tight fit reward: small post residual relative to item size means good packing
    score -= (item_size as f64 / cap) * 3.0;

    // Stream progression: early on, prefer consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress * 0.5);

    // Pull toward mean residual: avoid outlier bins
    score += (mean_residual - post as f64).abs() * 0.1;

    // New-bin candidate: only attractive when no good fit exists (large item, high mean residual)
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / cap) * 10.0 + mean_residual * 0.05 + (fitting_bins_count == 0) as i32 as f64 * 15.0;
        score = cap - desperation; // typically worse than reusing a decent bin
    }

    score
}

