    // late in the stream, strongly prefer minimal post_residual.
    let tightness = (pr / cap).powi(2);
    let mut score = pr * (1.0 + 2.0 * progress) + 40.0 * tightness * (0.5 + progress);

    // Reward filling bins deeply: subtract a smooth function of item size relative to capacity,
    // amplified as the stream progresses.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Dead-space penalty: post_residual too small to hold a plausible next item is wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // unusable for the known next item; penalize proportionally to the gap, smoothly
            score += 10.0 * ((nxt - pr) / cap) * (1.0 + progress);
        } else {
            // bonus for leaving room that exactly accommodates the next item
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).min(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: mildly penalize early in the stream (prefer using open bins),
    // but allow opening fresh bins late when residuals are fragmented (high mean_residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual - pr).abs()) / cap;
        score += 15.0 * (1.0 - progress) - 10.0 * progress * fragmentation;
    } else {
        // Slight preference for bins whose residual deviates from the mean (consolidate similar bins)
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are "useful"
    // (large enough to host typical future items) are rewarded; tiny
    // dead-space leftovers are heavily penalized.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else if pr <= 5 {
        // Nearly perfect but awkward: unusable sliver.
        score += 25.0;
    } else if pr <= 15 {
        // Small dead zone: penalize proportionally.
        score += 12.0 + (15 - pr) as f64;
    } else if pr <= 35 {
        // Medium zone: mildly useful.
        score -= 3.0;
    } else if pr <= 50 {
        // Sweet spot: half-bin leftovers accept most items.
        score -= 10.0;
    } else {
        // Large leftover: fine, but slight preference to spread load.
        score -= 2.0;
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 align
    // with the coarse granularity of item sizes, making future fits easier.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 >= 8 {
        // Just below a harmonic multiple: nearly a clean class.
        score -= 2.0;
    } else if pr % 10 <= 2 {
        // Just above a harmonic multiple: awkward.
        score += 3.0;
    }

    // Lookahead coupling: does the leftover admit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Bonus scaled by how snugly the next item nests.
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 - (snug / cap) * 4.0;
        } else if pr > 0 && pr < next_item_size {
            // Leftover too small for the lookahead item: dead space risk.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // Last item: prioritize tightest packing, no future value in space.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins unless the item is large
    // relative to capacity (fresh-bin fit is then inherently good) or the
    // stream is early and we expect many future items to fill it.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        score += 30.0 - fill_frac * 25.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If the new bin's leftover matches a harmonic class, soften penalty.
        if pr % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    let resid_frac = bin_residual as f64 / cap;
    score += resid_frac * 4.0;

    // Congestion-aware nudge: many open bins -> consolidate harder.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest items (<= ~10)
    // are effectively unusable; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger usable gaps: mild reward scaled by gap size.
        score -= 4.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Open-bin pressure: prefer reusing bins when many are open, but
    // relax pressure near the end of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = 1.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item fits poorly everywhere else (large item or high mean residual).
    if bin_residual == bin_capacity {
        let mean_res = mean_residual;
        // Attractive if open bins have large residuals anyway (poor fits there),
        // or the item is large and would leave a big gap anywhere.
        let poor_fit_elsewhere = mean_res > 35.0;
        let large_item = item_size > 60;
        if poor_fit_elsewhere || large_item {
            score -= 20.0;
        } else {
            score += 25.0;
        }
        // Extra penalty for opening bins early in the stream.
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item could use the post residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0; // leaves a sliver after next item
        }
    }

    // Mild deviation penalty: prefer bins whose residual is near the mean
    // to keep residual distribution balanced.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: small dead space is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }

    // If next item fits into the post residual, the pairing is efficient:
    // reward proportional to how well it fills the remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fill_ratio = next_item_size as f64 / post_residual as f64;
        score -= 300.0 * fill_ratio;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item would NOT fit here: post residual risks becoming dead space.
        // Penalize more when post residual is small (unusable) but not zero.
        if post_residual > 0 && post_residual < 10 {
            score += 150.0;
        }
        // Mild penalty scaled by how much slack is stranded.
        score += 0.3 * post_residual as f64;
    }

    // Compare post residual against mean residual: leaving less than average
    // stranded is desirable; leaving more is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 20.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave open bins with fragmented space.
    if bin_residual == bin_capacity {
        let base = 60.0;
        // In early stream, opening bins is cheaper; later, prefer packing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 5.0;
        // If next item is large, a fresh bin helps it fit later.
        let lookahead_help = if next_item_size > 50 { 40.0 } else { 0.0 };
        score += base + open_penalty - lookahead_help + 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits with a nonlinear bonus for small post_residual.
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)).ln() * 6.0;

    // Penalize dead space: residuals that are too small to be useful later.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or well,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= (30.0 - chain_waste as f64).max(0.0) * 0.8;
        } else {
            // Next item cannot follow here; penalize slightly more if this bin is scarce.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the emptiest (largest residual) to consolidate.
        score -= (bin_residual as f64 - mean_residual) * 0.4;
    }

    // Global consolidation pressure: many open bins -> prefer filling existing ones
    // over opening new bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln() / 4.0;
    score += pressure * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // New-bin candidate handling: make an empty bin attractive only when current
    // bins fit poorly (large post_residual elsewhere) or bin count is low.
    if bin_residual == bin_capacity {
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_elsewhere = fitting_bins_count == 0 || (post_residual as f64) < 15.0;
        if poor_fit_elsewhere {
            score -= 45.0 + 20.0 * (1.0 - time_frac);
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 60.0 + 40.0 * (1.0 - time_frac);
        }
    }

    // Mean residual coupling: when average residual is high, waste tolerance is higher;
    // when bins are nearly full, punish any wasted space harshly.
    let tightness = 1.0 - mean_residual / bin_capacity as f64;
    score += post_residual as f64 * tightness * 0.3;

    // Time horizon: late in the stream, prioritize closing out bins tightly.
    let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * time_frac * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) coupling to progress.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap * (0.4 + 0.6 * progress);

    // Dead-space penalty: tiny residuals are worthless late in the stream.
    let tiny = ((1.0 - norm_pr * 8.0).max(0.0)).powi(2);
    score += 30.0 * tiny * progress;

    // Reward tight fits: smooth polynomial in post_residual.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress * 0.5);

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    let lookahead_fit = if next_item_size > 0 { (1.0 - ((pr - next_item_size as f64).abs() / cap).powi(2)).max(0.0) } else { 0.0 };
    score -= 18.0 * lookahead_fit * (0.5 + 0.5 * progress);

    // Penalize blocking: next item larger than post_residual but bin was a good fit otherwise.
    if next_item_size > 0 && next_item_size as f64 > pr {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bonus: only fitting bin -> strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - is_new) * (0.6 + 0.4 * progress);
    }

    // New-bin candidate: prefer opening a new bin early, discourage late (bins are already sunk cost).
    score += is_new * (10.0 + 25.0 * progress);

    // Crowd effect: many open bins with high mean residual -> prefer consolidating into existing bins.
    let crowd = (open_bins_count as f64 / 20.0).min(1.5);
    score += is_new * 15.0 * crowd;
    score -= (1.0 - is_new) * 6.0 * crowd * (mean_residual / cap).powi(2);

    // Mild preference for bins whose residual deviates from mean (reduce variance smoothly).
    score += 4.0 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 - progress);

    // Item-size interaction: large items prefer emptier bins (smooth coupling).
    score += 12.0 * norm_item * norm_pr * (1.0 - progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are hard to fill later get penalized.
    let pr = post_residual;
    if pr > 0 {
        let r = pr % 10;
        // dead-space classes: residuals like 1..9 (mod 10) are nearly unusable
        if r > 0 && r < 10 {
            score += (10 - r) as f64 * 0.8;
        }
        // multiples of 10 are ideal slots
        if r == 0 { score -= 4.0; }
        // multiples of 5 are decent
        else if r == 5 { score -= 2.0; }
    } else {
        score -= 12.0; // perfect closure
    }

    // Integer-division thresholds on post_residual relative to next item
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // next item fits exactly / harmonically
            if pr == n { score -= 10.0; }
            else if pr % n == 0 { score -= 6.0; }
            else if pr / n >= 2 { score -= 3.0; }
            else { score += (pr - n) as f64 * 0.3; }
        } else {
            // next item cannot use this bin's leftover: leftover becomes dead weight
            score += (pr as f64) * 0.5;
            // but if leftover is large enough for generic future items (>=20), soften
            if pr >= 20 { score -= 5.0; }
        }
        // next item leaves a multiple-of-10 residue if placed here
        if n <= pr && (pr - n) % 10 == 0 { score -= 3.0; }
    }

    // Capacity fraction classes of current residual
    let frac = bin_residual as f64 / cap;
    if frac > 0.75 { score -= 2.0; }        // nearly full bin: good to pack
    else if frac < 0.25 { score += 1.5; }   // nearly empty bin: keep flexible

    // Last-chance bonus: only one fitting bin avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate: prefer it only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        if fragmentation > 0.5 && open_bins_count > 2 {
            score -= 3.0; // open bins are half-empty; new bin is fine
        } else {
            score += 15.0; // default: discourage opening new bins
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 && next_item_size > item_size {
            score -= 8.0; // big next item argues for a fresh bin
        }
    }

    // Late-stream: close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: raw leftover space.
    let mut score = post;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item (10) are pure waste; residuals 1..10 are heavily penalized,
    // while residuals that could still host a next item are mildly rewarded.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 6.0 * (10.0 - post); // unusable micro-gap penalty
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward small gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly favored
    }

    // Reward tight fits (waste ratio near zero).
    let waste_ratio = post / cap;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item can't fit, mild penalty.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
        // Coupling: penalty scaled by how far the next item misses.
        if next_item_size > post_residual {
            score += 0.3 * (n - post);
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual as u32 == bin_capacity) as f64;
    score += new_bin * (15.0 + 3.0 * open_bins_count as f64 + 10.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (i.e., already well-filled) to keep the residual distribution tidy.
    score += 0.5 * (mean_residual - post);

    // Slight preference for larger bins when residuals are comparable.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Near-match: next item fits with small leftover (tight two-item packing).
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 12.0 - 0.8 * gap;
        }
    }
    // Penalize when the next item cannot fit in the post residual (dead space chain).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Dead space: residual too small for any plausible item (min size 1, but small slivers are waste).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfectly closed bin is excellent
    }

    // Last-chance bonus: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Reward filling bins that are below the mean residual (consolidating slack).
    if (bin_residual as f64) < mean_residual {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    } else {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: discourage opening a new bin unless existing fit is bad.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 20.0 - 25.0 * pressure;
        if fitting_bins_count > 0 {
            score += 12.0; // some open bin fits; strongly prefer it
        }
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // stacking identical items in a fresh bin is fine
        }
    }

    // Early in the stream, slightly prefer opening bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing (even the next item) can use.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += (1.0 - usable) * (post_residual as f64).sqrt() * 2.5;
    }

    // Lookahead: strongly favor bins whose leftover fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 + 4.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = (1.0 - progress) * 10.0 + 2.0;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is more attractive when mean residual is fragmented.
        score -= (mean_residual / (bin_capacity as f64)) * 4.0
            + (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for fuller bins among open ones.
    score -= (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual scaled to [0,1], shaped by progress.
    let x = post_residual as f64 / cap;
    let p = progress;
    let shape = x * (1.0 + 0.8 * p - 0.9 * p * p * x);

    // Penalize large residuals more strongly as the stream progresses.
    score += 1.5 * shape * (1.0 + 2.0 * p * p);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 4.0 * (1.0 - x).powi(2) * (1.0 + p);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * p;
    }

    // Discourage scattering across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - x).abs();

    // Lookahead: penalize placements that leave a residual incompatible with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post_residual as f64 {
            score += 1.2 * (nx - post_residual as f64) / cap;
        } else {
            score -= 0.8 * (1.0 - (nx / cap).powi(2));
        }
    }

    // Mild bias against opening new bins early in the stream.
    score += 1.5 * (1.0 - p) * if bin_residual as f64 == cap { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual / 10).min(10); // integer division thresholds, 0..10
    let class_weight: [f64; 11] = [
        0.0,   // 0: perfect fit, golden
        1.0,   // 1: tiny residual, near-perfect
        4.0,   // 2: awkward small gap (only fits tiny items)
        6.0,   // 3
        7.0,   // 4
        5.0,   // 5: half bin, still very usable
        6.0,   // 6
        7.0,   // 7
        8.0,   // 8
        9.0,   // 9
        0.0,   // 10: untouched bin (new-bin candidate)
    ];
    score += class_weight[class as usize];

    // Reward exact and near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Harmonic lookahead: does next_item_size land in this bin's post_residual class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: chain bonus scaled by tightness of that fit.
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - next_tight * 0.3;
        } else {
            // Next item cannot use this bin: penalize proportional to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            // If bin is the item's last chance, accept imperfect fit rather than open a bin.
            if fitting_bins_count == 1 && bin_residual != bin_capacity {
                score -= 30.0;
            }
        }
    }

    // New-bin candidate handling: keep it attractive only when current bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bin when open bins are roomy; reward when they are tight.
        score += 20.0 + fragmentation * 60.0 - progress * 10.0;
        // If no other bin fits, opening is inevitable: make it the clear winner.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild bonus for choosing bins tighter than the mean (reduce global fragmentation).
    if !is_new_bin {
        let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += tightness * 15.0;
    }

    // Late-stream consolidation: prefer packing into fewer bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are almost unusable later
    // (item sizes >= 10 in classic regime, but allow for 1..100 regime with a
    // soft threshold around 12). Penalize landing in a dead zone.
    let dead_threshold = 12.0f64;
    if post_residual >= 1 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fits (small useful residual) mildly rewarded.
    if post_residual > 0 && post_residual <= 20 {
        score -= 8.0;
    }

    // Open-bin pressure: penalize spreading across many bins, but relax when
    // this is the only fitting bin (last chance before a new bin).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += (open_bins_count as f64) * 2.5;
    }

    // Prefer bins whose residual is close to the item (good coupling).
    let coupling = (bin_residual as f64 - item_size as f64).abs();
    score += coupling * 0.3;

    // Lookahead: if next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 * (1.0 - slack as f64 / 30.0).max(0.0);
    }

    // Discard opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0;
        // But if no existing bin can fit, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item leaves near-zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin is an excellent chain candidate.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward chains that keep residual small after the next item too.
            if slack_after_next <= 2 {
                score -= 200.0;
            } else {
                // Penalize leaving a large awkward gap after the next item.
                score += slack_after_next as f64 * 0.5;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty proportional
            // to how badly it misses (dead-space risk).
            let miss = next_item_size - post_residual;
            score += miss as f64 * 0.3;
        }
    }

    // Penalize creating dead space that no future small item (min size 1) would
    // plausibly fill relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to the capacity and no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 50.0;
        // Large items pack well into fresh bins; small items should reuse space.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 120.0 * frac;
        }
        // Early in the stream, new bins are cheaper (fewer alternatives).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If many bins are open, discourage adding more.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for tighter (smaller-residual) bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but zero-to-tiny leftover
    // after a big fill is excellent (perfect closure).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: if the next item could use the post_residual exactly
    // or nearly, reward leaving that gap; if next item is huge and won't fit
    // anyway, prefer compacting here.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (post_residual as f64 - nd).abs() < 6.0 {
            score -= 25.0; // post gap is a near-perfect slot for next item
        } else if (post_residual as u32) >= next_item_size {
            score -= 8.0; // next item can still fit here afterwards
        } else {
            // gap too small for next item: penalize proportionally to wasted gap
            score += 0.35 * post_residual as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Global state: many open bins with large mean residual -> prefer reusing
    // existing space (avoid bin proliferation).
    let pressure = mean_residual / bin_capacity as f64;
    score += 12.0 * pressure * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be conservative (favor new bins for
    // flexibility); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * fill_ratio;

    // Slight bias against the brand-new empty bin unless item is large or
    // no good fits exist.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.15 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Cubic coupling: early on, prefer tight fills (low post_residual); later, waste matters more.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize very small residuals (dead space) with a smooth saturation term.
    score += 15.0 * (-norm_pr * 8.0).exp() * (1.0 - progress);

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 20.0 * (1.0 - fit_ratio) * (0.4 + 0.6 * progress);
        } else {
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this residual is above mean (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: keep neutral-ish, slightly penalized early, allowed late.
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes create discrete "goodness" bands.
    let post = post_residual;
    let class = post % 10;
    // Dead-space penalty: residuals that can't fit common small items are bad.
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    } else if post == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Harmonic reward: residuals in friendly classes (multiples of 5/10) are reusable.
        if class == 0 {
            score -= 12.0;
        } else if class == 5 {
            score -= 6.0;
        }
        // Integer-division tiers on post_residual: small leftovers preferred over mid gaps.
        let tier = post / 20; // 0..5
        score += tier as f64 * 3.0;
    }

    // Perfect harmonic pairing: post_residual exactly equals next item size.
    if next_item_size > 0 && post == next_item_size {
        score -= 30.0;
    }
    // Next item fits harmonically into the leftover with class alignment.
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap % 10 == 0 {
            score -= 8.0;
        } else if gap < 10 {
            score += 10.0; // leaves sliver after next placement
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin early in stream or when open bins are already tight.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post < 15 || (post < 30 && pressure > 0.5) {
            score -= 15.0 + 20.0 * (1.0 - progress);
        } else {
            score += 30.0; // discourage opening new bins when fit is decent
        }
    }

    // Mild preference for filling bins with larger residual when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
