        score += (1.0 - usable) * (post_residual as f64).sqrt() * 2.5;
    }

    // Lookahead: favor bins whose leftover fits the next item, scaled by how
    // "valuable" that leftover is (large leftovers that still fit next are best).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 + 4.0 * (1.0 - gap / cap);
        // Extra coupling: if the remainder after next item is tiny, this is a
