        if gap <= 3.0 {
            score -= 5.0;
        } else if gap > cap * 0.45 {
            // Leftover after next item is still big: good, reusable space.
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close it was.
        let miss = (next_item_size - post_residual) as f64;
        score += 3.0 + (miss / cap) * 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin,
    // but only when the fit isn't terrible (post_residual small relative to item).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.25 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = (1.0 - progress) * 10.0 + 2.0;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is more attractive when mean residual is fragmented
        // OR when many bins are already open with poor fits available.
        score -= (mean_residual / cap) * 4.0 + (open_bins_count as f64).ln().max(0.0);
        // If the next item is large and no open bin can hold it, a fresh bin
        // guarantees a home — discount the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size > item_size {
            score -= 3.0;
        }
    }

    // Slight preference for fuller bins among open ones.
    score -= (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
