        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to
        // how much space will be stranded relative to the next item.
        score += 3.0 + (post_residual as f64) / (next_item_size as f64).max(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
