        // Opening a new bin is more attractive when mean residual is fragmented
        // or many bins are already open.
        score -= (mean_residual / cap) * 5.0
            + (open_bins_count as f64).ln().max(0.0) * 1.5;
        // A fresh bin is especially good for large items that would strand
