    score -= (bin_residual as f64) * 0.022;

    // Absolute waste floor: heavily penalize leaving more than 40% of the
    // capacity unused unless the residual can host the next item.
    if post_residual as f64 > cap * 0.4 && !(next_item_size > 0 && next_item_size <= post_residual) {
