    // to plausibly host future mid-size items (adaptive threshold).
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        let big_enough = (post_residual as f64) >= mean_residual * 0.75;
        let dead = (post_residual as f64).sqrt() * if big_enough { 1.4 } else { 3.2 };
        score += (1.0 - usable) * dead;
    }

    // Lookahead: favor bins whose leftover fits the next item, scaled by
    // how snugly the next item nests in the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 7.0 + 5.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // If next item cannot fit here, mildly penalize, but less so when
        // many bins remain open (options preserved).
        score += if fitting_bins_count > 2 { 1.5 } else { 4.0 };
    }

    // Last-chance bonus: sole fitting open bin should win over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Size-aware coupling: large items prefer already-dense bins.
    let item_frac = (item_size as f64) / cap;
    if item_frac > 0.5 {
        score -= (bin_residual as f64) * 0.05;
    } else {
        score -= (bin_residual as f64) * 0.015;
    }

    // New-bin decision: baseline penalty decays with stream progress, but
    // opening a bin becomes attractive when mean residual is high (fragmented
    // state) or when the item is large and no open bin has roomy leftovers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = (1.0 - progress) * 9.0 + 2.0;
        // Fragmentation pressure: high mean residual => prefer fresh bin.
        new_bin_penalty -= (mean_residual / cap) * 6.0;
        // Few open bins => cheaper to open one.
        new_bin_penalty -= (open_bins_count as f64).ln().max(0.0) * 1.5;
        // Large items deserve clean space when leftovers are all tight.
        if item_frac > 0.5 && mean_residual < cap * 0.2 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty;
    }

    score
}

