    // Base: prefer tight fits (low post_residual), with mild superlinearity
    // to strongly punish leaving medium dead space.
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward bins whose post_residual can
    // accommodate the next item (a "chain fit").
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chain fit is the jackpot.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // The next item won't fit here: penalize proportionally to how
            // much dead space we strand relative to the next item's size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average residual is good (we packed tighter than typical).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has a large residual, so its
    // raw score is high. Give it a calibrated offset so it wins only when
    // open bins would strand a lot of dead space.
    if bin_residual == bin_capacity {
        // New bin: neutral base plus lookahead for the next item.
        score = 45.0 + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap; late, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
    }

    // Mild preference to fill existing bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no plausible item (>=1) can use well:
    // residuals of 1..9 are nearly unusable -> hard penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins -> prefer consolidating into existing ones.
    score += 0.4 * open_bins_count as f64;

    // Encourage placing into bins with below-average residual (balance-aware).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Time horizon: early in stream, be more willing to open fresh bins
    // (keep flexibility); later, force tight consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 20.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // New bin is attractive if item is large and nothing fits well.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Late stream: prioritize exact-ish packing even more.
    score -= t * 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Smooth polynomial base: reward small post_residual, with mild curvature
    let mut score = pr
        - 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * it / cap * 10.0;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costlier)
    let tightness = 1.0 - fit_ratio * fit_ratio;
    score -= 8.0 * progress * tightness * tightness;

    // Penalize perfect-fit waste early vs. late via smooth interaction
    score += 4.0 * fit_ratio * (1.0 - progress) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let smooth = 1.0 / (1.0 + gap * gap / 50.0);
        score -= 10.0 * smooth;
    }

    // Slight penalty for very full bins relative to fleet mean residual
    score += 2.0 * (mean_residual - pr) / cap;

    // Mild pressure to prefer existing bins over new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" residue class (divisible into common item sizes) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: eliminate the bin entirely
    } else {
        // Residue-class bonus: leftover that is a multiple of small harmonics
        // (5, 10, 20, 25) tends to be exactly fillable by later items.
        let harmonic_bonus = if pr % 10 == 0 { 12.0 }
            else if pr % 5 == 0 { 6.0 }
            else if pr % 20 == 0 { 10.0 }
            else { 0.0 };
        score -= harmonic_bonus;

        // Dead-space penalty: tiny unusable leftovers (1..9) are worst.
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits, but leaves a residue: mild reward scaled by fit tightness
            let tight = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 15.0 + 20.0 * tight;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers a bit
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // cheaper to open a new bin early in the stream or when bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // if mean residual across open bins is large, new bin is attractive
        score -= (mean_residual - cap * 0.3).max(0.0) * 0.3;
    }

    // Prefer tighter fits generally: penalize by fraction of capacity wasted.
    score += (pr as f64 / cap) * 15.0;

    // Slight penalty for spreading across many open bins (encourage closing bins).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever be useful (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: residual close to item size means good packing.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading when bins are numerous.
    score += (open_bins_count as f64) * 1.5;

    // If next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // or the item fits nowhere tightly.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progression: later in stream, slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

