pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed non-linearly
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in stream, penalize large residuals more (dead space costs compound)
    let prog_coupling = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += prog_coupling * pr * 0.5;
    score -= progress * 20.0 * (1.0 - norm_pr); // reward tight fits more as stream ends

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let miss = (nx - pr) / cap;
            score += 30.0 * miss * miss * cap;
        } else {
            // reward residual that exactly accommodates lookahead
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty for wasting this bin's flexibility
        score += 3.0 * (fitting_bins_count.min(10) as f64) * norm_pr;
    }

    // Mean residual context: prefer bins below mean residual (tighter bins first)
    score += 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize slightly so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
