    // 2-step lookahead: reward when next item exactly fills the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.5 + 4.5 * (1.0 - gap / cap_f);
        if gap == 0.0 {
