        }
        if gap > 0.0 && gap >= next_item_size as f64 {
            score -= 2.5;
        }
        if gap > 0.0 && (gap as u32) >= next_item_size {
            score -= 1.5 * (1.0 - gap / post_residual as f64);
        }
        if gap > 0.0 && gap >= next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 1.2;
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 1.0 * (1.0 - gap / 8.0);
        }
        if gap as u32 >= 2 * next_item_size {
            score -= 1.5;
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 0.8 * (1.0 - gap / 4.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        score += 3.2 + 0.02 * post_residual as f64;
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
            score += 1.0;
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.01 * cap_f + 0.004 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 0.8;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + 12 <= bin_residual && item_size + 12 < next_item_size {
            score -= 2.2;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.6;
        }
        // Allow new bin when open bins are highly fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
