    // Next item fits and residual stays within 2x next item with many alternatives.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
