        if gap > 0.0 && gap < 4.0 {
            score -= 0.8 * (1.0 - gap / 4.0);
        }
        if gap > 0.0 && gap >= next_item_size as f64 && fitting_bins_count <= 2 {
            score -= 1.2;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit here; penalize more for near-miss residuals.
        score += 3.2 + 0.02 * (post_residual as f64);
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
            score += 1.0;
        }
    }

    // Exact item fit bonus.
    if item_size == bin_residual {
        score -= 10.5;
    } else if item_size >= bin_residual {
        score -= 2.0;
    }

    // Post-residual that cannot host the next item: penalize small traps.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.05;
    }
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 1.0;
    }
    if post_residual > 0 && post_residual < next_item_size && post_residual < bin_capacity / 10 {
        score += 2.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // Open-bin pressure: keep bin count in check as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 8.0 * progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    }

    // Last-chance bin: strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling (softened to avoid over-homogenizing).
    score += ((bin_residual as f64 - mean_residual) / cap_f).abs() * 3.0;

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (mean_residual < item_size as f64 && open_bins_count > 0);
        if desperate {
            score -= 30.0;
        } else {
            score += 25.0 + (open_bins_count as f64) * 0.5;
            // Allow opening a new bin when the item is huge and would leave
            // open bins too fragmented for the lookahead item.
            if next_item_size > 0 && fitting_bins_count > 0
                && item_size as f64 >= 0.6 * cap_f
                && item_size + 12 <= bin_residual
                && item_size + 12 < next_item_size {
                score -= 2.2;
            }
            if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
                score -= 0.8;
            }
            if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
                score += 0.6;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..=9)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using bins that would otherwise waste large residuals,
    // and penalize placements into already-tight bins when alternatives exist.
    if post_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 12.0;
    }

    // 2-step lookahead: reward when next item fits into the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 4.5 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 4.0; // exact 2-chain
        }
        if gap > 0.0 && (gap as u32) < next_item_size {
            score -= 1.5; // gap smaller than next item: near-closed bin
        }
        if gap > 0.0 && (gap as u32) >= 2 * next_item_size {
            score -= 1.0; // room for another copy of next item
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 1.0 * (1.0 - gap / 8.0);
        }
        if gap > 0.0 && fitting_bins_count <= 2 {
            score -= 1.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 2.0 + 0.02 * dead;
            if post_residual < next_item_size / 2 {
                score += 2.0;
            }
            if post_residual < next_item_size && post_residual < cap_f / 10.0 {
                score += 1.5;
            }
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 2.0 * (1.0 - post_residual as f64 / cap_f);

    // Exact fill of current residual.
    if item_size == bin_residual {
        score -= 10.0;
    }

    // Last-chance bin: favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: unattractive unless existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.01 * cap_f + 0.004 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 0.8;
        }
        if next_item_size > 0 && fitting_bins_count > 0
            && item_size + 12 <= bin_residual
            && (item_size + 12) < next_item_size
