    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Early stream: slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 1.0 * (1.0 - progress);

    score
}

