pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but the penalty for leftover space grows
    // super-linearly as the stream progresses (dead space becomes
    // progressively less likely to be filled later on).
    let tightness = 1.0 - norm_pr;
    let progress_amp = 0.5 + 1.5 * progress * progress;
    let mut score = pr * (1.0 + progress_amp * (1.0 - tightness * tightness));

    // Smooth coupling: small post-residuals are rewarded more when the
    // mean residual across open bins is low (bins are nearly packed).
    let mean_norm = mean_residual / cap;
    score -= (1.0 - norm_pr) * (1.0 - mean_norm) * cap * 0.15 * (0.5 + progress);

    // Lookahead: reward a post-residual that exactly accommodates the
    // next item; penalize near-miss residuals that waste capacity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // smooth reward decaying with the gap size
            score -= 12.0 * (-gap / 20.0);
        } else {
            score += 6.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count > 0 {
        score -= 20.0 / fitting_bins_count as f64;
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += open_bins_count as f64 * (1.5 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small
    // integers are more likely to be filled exactly by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward "harmonic" residuals: divisible by 10, 5, 25, 50.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Penalize dead space in awkward classes (prime-ish, small odd gaps)
        if pr < 10 { score += 20.0; }
        else if pr < 20 && pr % 2 == 1 { score += 6.0; }
    }

    // Lookahead coupling: does next_item_size fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // keeps a viable slot for the next item
            // exact two-item closure: post_residual == next_item_size
            if post_residual == next_item_size { score -= 15.0; }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are crowded or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly; relief when few fitting bins or large item.
        score += 18.0
            - 25.0 * (fitting_bins_count as f64).recip()
            - 10.0 * (item_size as f64 / cap)
            - 8.0 * crowding
            + 5.0 * progress;
        // Harmonic bonus: an empty bin has perfectly harmonic residual.
        score -= 4.0;
    }

    // Fraction-of-capacity thresholds on bin_residual: bins in the lower
    // half of capacity are more valuable to fill up.
    let fill_frac = 1.0 - bin_residual as f64 / cap;
    if fill_frac > 0.5 { score -= 3.0; }
    if fill_frac > 0.75 { score -= 3.0; }

    // Mild pressure against accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    // Integer-division threshold: quantize post_residual into buckets of 10
    // and prefer lower buckets (tighter packing granularity).
    score += (post_residual / 10) as f64 * 0.5;

    score
}

