        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; a large leftover would be wasted
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean; placing into a below-mean residual bin leaves other bins flexible.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Progress-based calibration: early in the stream, keep bins flexible (mild penalty
    // for large fill); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill_ratio;

    // New-bin candidate handling: only open a new bin if it's genuinely needed
    // (no good existing fit). New empty bin gets a base cost so it loses to decent fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream with many open bins, opening a new bin is even less attractive
        score += 10.0 * progress;
        // But if open bins are all nearly full (low mean residual), a new bin is fine
        if mean_residual < 25.0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled against mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chained packing), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain match is gold: next item fills this bin perfectly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0) * 0.6;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall,
            // but mildly — a small dead space may still be the best choice.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.4;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is huge
    // relative to capacity (would leave open bins cluttered with tiny residuals).
    if bin_residual == bin_capacity {
        let mut new_penalty = 25.0;
        // Large items (>= 60% of capacity) justify a fresh bin.
        if item_size as f64 >= 0.6 * bin_capacity as f64 {
            new_penalty -= 20.0;
        }
        // If no existing bin can fit (fitting_bins_count == 0 among open bins),
        // the new bin is forced — remove penalty.
        if fitting_bins_count == 0 {
            new_penalty = 0.0;
