        // (later in the stream, fewer expected future items -> cheaper to open).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * (1.0 - 0.5 * progress);
        // If an empty bin is being compared, penalize using it for small items.
        score += 0.2 * (bin_capacity - item_size) as f64;
