    // early on, waste matters less (many items left to fill gaps);
    // late, dead space is increasingly costly -> amplify post_residual.
    let progress_coupling = post * (0.5 + 1.5 * progress * progress);
    score += 0.35 * progress_coupling;

    // Reward tight fits non-linearly: normalized fill ratio of the placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize leaving a "dead sliver": post residual too small for the
    // smallest plausible item (1..100 range). Smooth quadratic penalty near 0.
    let sliver = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 30.0 * sliver * sliver;

    // Lookahead: if the next item fits in post_residual, reward this bin
    // (chaining placements); scale reward by how snugly the next item fits.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - post / cap;
