    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item
    // (size 1) are pure waste, but residuals that are "small but usable" are
    // worse than residuals that are exactly zero. Penalize tiny nonzero gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space coupling: penalize residuals that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }
    // Reward residuals that accommodate the next item comfortably.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting; with few bins, tolerate new bins.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * bin_pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins; make it moderately expensive so it is chosen only when fits
    // are poor, scaled by stream progression (late stream => consolidate more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress + 0.1 * open_bins_count as f64;
    }

    // Mild penalty for leaving large residuals when mean residual is already
    // high (bins are fragmented); reward when it reduces fragmentation.
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
