    // open bins exist and mean residual is high (fragmentation guard).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score -= consolidation * 0.8 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bins attractive only when the item is
