        score += 4.0 * (mean_residual - bin_residual as f64) / cap;
    }

    // New-bin candidate: make it attractive only when few fitting bins exist
    // or the item is large relative to typical residuals; otherwise discourage.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let size_pull = item_size as f64 / cap;
        score -= 30.0 * scarcity * size_pull * (0.5 + progress);
        score += 10.0 * (1.0 - scarcity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap_f / 4.0;

    // Exact-fit reward: zero post residual is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize residuals that fall into "dead" harmonic classes: too small for
    // the minimum plausible item (1..100 interface, but typical sizes are large).
    let min_useful = 10.0f64.min(cap_f / 10.0);
    if post > 0.0 && post < min_useful {
        score += 200.0; // unusable sliver
    }

    // Harmonic class reward: residuals expressible as nice fractions of capacity
    // (cap/2, cap/4, cap/8 ...) are more likely to be reusable.
    let mut harmonic_bonus = 0.0;
    let mut denom = 2.0;
    while denom <= 64.0 {
        let target = cap_f / denom;
        if (post - target).abs() < 0.5 {
            harmonic_bonus = 40.0 / denom;
        }
        denom *= 2.0;
    }
    score -= harmonic_bonus;

    // Lookahead coupling: reward residuals that exactly fit the next item
    // (harmonic chain), penalize residuals that waste the next item's fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post - nx).abs() < 0.5 {
            score -= 300.0; // perfect chain placement
        } else if post >= nx {
            score -= 30.0; // next item can still land here
        } else {
            score += 50.0; // next item won't fit this residual
        }
        // Modulo-class coupling: if post_residual mod next_item_size is small,
        // the residual can be tiled efficiently later.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Integer-division thresholds on post_residual.
    let class = post_residual / (bin_capacity / 10).max(1); // decile class
    score += class as f64 * 2.0; // mildly prefer smaller decile classes beyond raw value

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the current bin would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post > 0.0 && post < min_useful * 2.0;
        if bad_fit && progress > 0.1 {
            score -= 120.0; // prefer opening a fresh bin over creating dead space
        } else {
            score += 80.0; // keep filling open bins by default
        }
    }

    // Mild pressure toward compacting many open bins.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose post residual stays
    // near the fleet average to keep classes balanced.
    score += (post - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small positive gaps are the worst outcome.
    // A tiny unusable residual (1..=10) is heavily penalized beyond its raw size.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still hold the smallest plausible item (>=1),
    // with extra reward if the residual can fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if post_residual > 0 && post_residual < 10 {
        // dead zone: gap too small for anything useful in practice
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing bins (penalize new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below mean residual (loose bins) when gaps are equivalent.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }
    if item_size == bin_residual {
        score -= 10.0;
    }

    // 2-step lookahead: reward when next item fits the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        if gap > 0.0 && (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
        if gap > 0.0 && gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.5;
            }
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
            score += 1.2;
        }
        // Extra: gap that still fits next item again (chain fit).
        if gap > 0.0 && gap >= next_item_size as f64 && gap < 2.0 * next_item_size as f64 {
            score -= 1.0;
        }
        // Extra: tiny gap after next item is near-waste.
        if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
            score -= 0.8;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        let dead = post_residual as f64;
        score += 3.2 + 0.02 * dead;
        if dead > 0.0 {
            score += 42.0 * (1.0 - dead / cap_f);
        }
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
            score += 1.0;
        }
        if post_residual > 0 && post_residual < bin_capacity / 12 {
            score += 2.2;
        }
        // Extra: residual below mean*0.6 is likely stranded.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score += 1.0;
        }
    }

    // Tight fit reward.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 1.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.8;
        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        // Waste-risk guard from best heuristic.
        let waste_risk = if next_item_size > 0 && next_item_size <= bin_capacity {
            0.0
        } else {
            6.0
        };
        score += waste_risk + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
    }

    // Dead-space usability term: reward bins whose residual stays usable.
    if post_residual > 0 && next_item_size > 0 {
        let usable = (post_residual >= next_item_size) as i32 as f64;
        score -= 1.5 * usable * (1.0 - post_residual as f64 / cap_f);
    }

    // Mild penalty for deviating from mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

