    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global balance: prefer bins near the mean residual to keep diversity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well
