    if bin_residual == bin_capacity {
        let open_benefit = if fitting_bins_count == 0 { -20.0 } else {
            let avg_waste = mean_residual - item_size as f64;
            if avg_waste < 5.0 { 5.0 } else { 15.0 + 0.3 * open_bins_count as f64 * (1.0 - t) }
        };
        score += 80.0 + open_benefit;
    }

    score
}

