pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: favor tight fits (low post-residual), with smooth non-linear shaping
    let mut score = prn * (1.0 + 0.8 * prn * prn);

    // Non-linear coupling: tight fits are progressively more valuable as stream advances
    let tightness = 1.0 - prn;
    score -= 2.5 * progress * tightness * tightness * tightness;

    // Penalize dead space that is too small to hold even the next item (smooth)
    let nx = next_item_size as f64 / cap;
    let unusable = (nx - prn).max(0.0) * (1.0 - prn).max(0.0);
    score += 1.5 * unusable * (1.0 + progress);

    // Reward using bins that fit (avoid unnecessary new bins), smoothly
    if fitting_bins_count > 0 {
        score -= 0.5 * (fitting_bins_count.min(5) as f64).ln().max(0.0);
    }

    // Late-stream: prefer closing bins near-full; early: keep slack for future items
    score += 0.6 * (1.0 - progress) * prn;
    score -= 0.4 * progress * (mean_residual / cap) * (1.0 - prn);

    // Slight penalty for opening new bins when many already open
    score += 0.3 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let usable = ((pr % 10 == 0) as i32) * 2
        + ((pr % 5 == 0) as i32)
        + ((pr % 20 == 0) as i32) * 2
        + ((pr % 25 == 0) as i32)
        + ((pr % 50 == 0) as i32) * 3;
    score -= 4.0 * usable as f64;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Integer-division threshold: classify leftover into capacity fifths.
    let fifth = pr / 20;
    score -= match fifth {
        0 => 0.0,          // 0..19 : nearly dead
        1 => 2.0,          // 20..39: fits small items
        2 => 5.0,          // 40..59: mid utility
        3 => 8.0,          // 60..79: high utility
        _ => 10.0,         // 80..100: nearly empty bin
    } * (bin_capacity as f64 / 100.0);

    // Lookahead coupling: reward leftovers that can host the next item exactly
    // or with a good harmonic match.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem == 0 || rem % 10 == 0 || rem % 5 == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot fit here; slight penalty if this bin was the
            // only candidate (forcing a new bin anyway).
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && pr < bin_capacity {
        score -= 30.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a tight fit. Make the empty bin mediocre by default.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheap; early on, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (consolidating space usage).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure against bin sprawl.
    score += 0.05 * open_bins_count as f64;

    // Exact-fill celebration.
    if pr == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
