    }
    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Lookahead: if next item can use the leftover space, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
