    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current placement wastes space.
    if bin_residual == bin_capacity {
        score += 20.0;
