    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps next item placeable here
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin could have held the next item instead; mild penalty.
            score += 6.0;
        }
        // Bonus if post_residual exactly matches next item's complement style.
        if post_residual > 0 && post_residual + next_item_size <= bin_capacity && post_residual >= next_item_size {
            score -= 3.0;
        }
