    // late in the stream, just use bins freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
