    // Mild pressure toward consolidating into existing bins as stream progresses
    score -= prog_poly * 4.0 * norm_item;

    // Mean residual coupling: prefer bins below mean residual (tighter fits)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
