pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / cap_f);
            // small gaps are dangerous dead space after next item
            if gap > 0.0 && gap < 8.0 {
                score -= 2.2 * (1.0 - gap / 8.0);
            }
            if gap > 0.0 && gap < 4.0 {
                score -= 1.0 * (1.0 - gap / 4.0);
            }
            // gap large enough to hold next item again is good
            if gap as u32 >= next_item_size {
                score -= 2.5;
                if fitting_bins_count <= 2 {
                    score -= 1.5;
                }
            }
            // room for multiple repetitions of next item
            if (gap as u32) >= 2 * next_item_size {
                score -= 1.8;
            }
            if (gap as u32) >= 3 * next_item_size {
                score += 1.0;
            }
            // gap slightly below next item is awkward
            if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
                score += 1.2;
            }
            if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
                score -= 0.8;
            }
        } else {
            // next item won't fit here; penalize wasted space
            let dead = post_residual as f64;
            score += 3.2 + 0.02 * dead;
            if dead > 0.0 {
                score += 42.0 * (1.0 - dead / cap_f);
            }
            if post_residual < next_item_size / 2 {
                score += 2.5;
            }
            if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
                score += 1.0;
            }
            if post_residual > 0 && post_residual < bin_capacity / 12 {
                score += 2.2;
            }
            if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
                score += 1.0;
            }
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 600.0;
    }

    // Fragmentation relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 200.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // fresh bin attractive when open bins are fragmented
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 260.0;
        }
        // big item now, next item big too: fresh bin may serve both
        if next_item_size > 0 && next_item_size <= post_residual && item_size as f64 >= 0.5 * cap_f {
            score -= 40.0;
        }
        // avoid opening a fresh bin when the remaining slack is already generous
        if fitting_bins_count > 0 {
            let slack = pr / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 1.5;
        }
        score += 0.5 * open_bins_count as f64;
    }

    // Mild consolidation pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny dead space
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // Anything below the minimum item size (1) is pure waste, but gaps that
    // are too small to be useful relative to the incoming stream are worse.
    if post_residual > 0 && post_residual < item_size {
        // dead space smaller than the current item => likely unusable later
        score += 12.0 * (1.0 - post_residual as f64 / item_size as f64);
    }
    if post_residual > 0 && post_residual < 10 {
        // tiny gap: essentially dead space
        score += 20.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 5.0 * (post_residual as f64 - next_item_size as f64) / 100.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // would leave next item needing another bin: penalize
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (a new empty bin call has bin_residual == bin_capacity, so give it a
    // handicap proportional to open_bins_count).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        // slight preference to fill already-open bins as pressure grows
        score -= 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Mean residual coupling: bins far below mean residual are "loose" bins;
    // prefer packing into tight bins (low residual) when mean residual is high.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Late-stream tightening: as stream progresses, avoid leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-item closure of this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward tight chains, penalize wasteful leftovers
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: dead space risk
            score += 12.0;
            // extra penalty if dead space is small and unusable
            if post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer closing bins as tightly as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Prefer filling bins with large residual when many bins are open
    score += 0.2 * (open_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins mid-stream when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
        // but allow new bin if next item is large and post_residual tiny elsewhere
        if next_item_size > 50 && post_residual < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize more if the leftover becomes waste.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: any placement is fine; reward using an existing bin.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (prefer good fits, keep bins balanced);
    // late in the stream, prioritize simply closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    // Global state coupling: when many bins are open with large mean residual,
    // encourage consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let consolidation = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
        score -= 3.0 * consolidation * tightness;
    }

    // New-bin candidate handling: only attractive when nothing decent is open.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0 // no open bin fits; new bin is the only option
        } else {
            // Slight preference to use existing bins unless they'd all waste heavily.
            let avg_waste = (mean_residual - item_size as f64).max(0.0);
            20.0 + 0.5 * avg_waste.min(60.0)
        };
        // A fresh bin has full residual; pull its score toward competitiveness.
        score = score * 0.5 + desperation;
    }

    score
}

