pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Next item fits afterwards: reward tighter resulting gaps.
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        if gap > 0.0 && (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
        if gap > 0.0 && gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.5;
            }
        }
        if gap > 0.0 && gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
            score += 1.2;
        }
        if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
            score -= 0.8;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        let dead = post_residual as f64;
        score += 3.2 + 0.02 * dead;
        if dead > 0.0 {
            score += 42.0 * (1.0 - dead / cap_f);
        }
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
            score += 1.0;
        }
        if post_residual > 0 && post_residual < bin_capacity / 12 {
            score += 2.2;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score += 1.0;
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: unattractive unless existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 1.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.8;
        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        let waste_risk = if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 6.0 };
        score += waste_risk + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;
    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && pr > 0.0 {
            score += 25.0 * (1.0 - pr / nx) * (1.0 - progress);
        } else if pr >= nx {
            score -= 5.0 * (pr / cap) * (pr / nx).min(3.0);
        }
    }
    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }
    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets
    // via integer division on the capacity. Small classes (tight fits) are rewarded.
    let class = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - class as f64) * 4.0; // tighter fit (small class) => lower score

    // Perfect / near-perfit classes get strong bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Modulo arithmetic on capacity fractions: penalize dead space that no
    // typical item (1..100) can plausibly fill later.
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.10 {
        score += 40.0; // sliver dead space, hard to reuse
    }

    // Next-item lookahead: harmonic class of next item vs post_residual
    if next_item_size > 0 {
        let next_class = next_item_size / 10;
        if (next_item_size as f64) <= post_residual as f64 {
            // next item fits here too: reward reserving this bin's harmony
            score -= 8.0 + next_class as f64;
        } else {
            // next item won't fit: penalize leaving a mismatched class
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
        // exact harmonic pairing: post_residual == next_item_size
        if next_item_size == post_residual {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish baseline; penalize so we prefer decent existing fits,
        // but allow opening when existing residuals are tiny relative to item
        score += 55.0;
        if post_residual as f64 > mean_residual {
            score -= 20.0; // fresh bin keeps large usable residual
        }
        // late in stream, prefer consolidating rather than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Many open bins: encourage filling existing ones harder
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space relative to next item
        score += 0.35 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.02 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 20.0; // big item coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }
    if item_size == bin_residual {
        score -= 10.5;
    } else if item_size >= bin_residual {
        score -= 2.0;
    }

    // 2-step lookahead: reward when next item fits the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        if gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        if gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.5;
            }
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
        if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
            score -= 0.8;
        }
        if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
            score += 1.2;
        }
    } else if next_item_size > 0 {
        // Dead-space penalty for bins the next item cannot use.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 3.2 + 0.02 * dead;
            score += 42.0 * (1.0 - dead / cap_f);
            if dead < 20.0 {
                score += 2.0;
            }
            if post_residual < bin_capacity / 12 {
                score += 2.2;
            }
            if (post_residual as f64) < mean_residual * 0.6 {
                score += 1.0;
            }
            score += (next_item_size - post_residual) as f64 * 0.05;
            if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
                score += 1.0;
            }
            // New: stronger penalty when the residual is a sliver compared to next item.
            if (post_residual as f64) < (next_item_size as f64) * 0.25 {
                score += 1.5;
            }
        }
    }

    // Tight fit reward.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 1.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.8;
        }
        if next_item_size > 0 && item_size + 12 <= bin_residual && item_size + 12 < next_item_size {
            score -= 2.2;
        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
        // New: open fresh bins more freely late in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.75 && fitting_bins_count > 0 {
            let avg_fit = mean_residual / open_bins_count.max(1) as f64;
            if avg_fit < (next_item_size as f64) * 0.5 {
                score -= 30.0;
            }
        }
        // New: discourage opening when next item could exactly fill a residual-sized hole.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score += 3.0;
        }
    }

    // Balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: spread slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // Chain-fill reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // New: prefer bins whose post-residual matches the next item exactly across the stream.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item fits afterwards: mild reward proportional to slack quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space more
            // when the leftover is small (unusable).
            let dead = next_item_size - post_residual;
            if dead <= 10 {
                score += 80.0;
            } else {
                score += dead as f64 * 0.5;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to residual or many bins are open.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 150.0 - 200.0 * big_item;
        if open_bins_count == 0 {
            score -= 500.0; // must open the first bin
        }
    }

    // Late in the stream: consolidate, avoid spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post-residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize more if this bin is nearly full anyway.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: when many bins are open, discourage fragmentation;
    // when few bins are open, be more permissive.
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += openness * (post_residual as f64 * 0.35);

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of bin sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // Time horizon: late in the stream, be conservative (minimize waste);
    // early, allow exploratory placements.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 10.0 * fit_ratio;
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight bonus for perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual, with non-linear shaping
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early: prefer tight fills less aggressively; late: strongly minimize post_residual
    let progress_weight = 0.5 + 2.5 * t * t;
    score += progress_weight * (pr * pr) / cap;

    // Smooth fit quality term: normalized fill fraction, cubic coupling
    let fill = (item / cap) * (item / cap);
    score -= 20.0 * fill * (1.0 + t) * (1.0 - (pr / cap) * (pr / cap));

    // Lookahead: reward if next item fits in post_residual (smooth sigmoid-like)
    if nxt > 0.0 {
        let fits = (pr - nxt).max(0.0) / cap;
        let slack = (nxt / cap) * (1.0 - (pr / cap).min(1.0));
        score -= 8.0 * fits * (1.0 + slack);
        // penalize post_residual too small for next item (dead space risk)
        let miss = (nxt - pr).max(0.0) / cap;
        score += 6.0 * miss * miss * (1.0 + t);
    }

    // Last-chance bin: strongly favor using it (smooth coupling with fitting count)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + t);
    }

    // Penalize bins far below mean residual (fragmentation avoidance), smooth quadratic
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 4.0 * dev * dev;

    // Many open bins: mild preference to consolidate
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
