pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes (items >= 10 typically)
    let class = post_residual % 10;
    // Dead space penalty: residuals in awkward classes (1..9 mod 10) are less reusable
    if class != 0 && post_residual > 0 {
        score += (10 - class) as f64 * 0.35;
    }
    // Perfect residual classes divisible by 10 are highly reusable
    if class == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Tight fit reward: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 4.0;

    // Exact fill bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item fits into post_residual at all, mild reward
    if next_item_size > 0 && next_item_size <= post_residual && next_item_size >= post_residual / 2 {
        score -= 3.0;
    }
    // Penalize if post_residual is a dead zone: smaller than any plausible item (harmonic floor)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last chance: only this bin can fit the item -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Bias slightly against new bins early; allow later when mean residual is low
        score += 4.0 + 6.0 * (1.0 - progress) - (mean_residual / bin_capacity as f64) * 5.0;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else if (bin_residual as f64) < mean_residual - 1.0 {
        // Bins tighter than average are good targets
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
