    // existing bins rather than spreading; opening new bins becomes costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (8.0 + 12.0 * progress);
    score += pressure;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item
    // is large and would leave a very tight gap elsewhere, or when no open
    // bin fits well. Otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count == 0 || (gap > 0.0 && gap < 5.0);
        if tight_elsewhere {
            score -= 10.0;
        } else {
            score += 30.0 + pressure;
        }
    }

    // Lookahead coupling: if the next item would fit nicely in the post
    // residual, reward this placement (chain-friendly gaps).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if gap >= ni && gap - ni < 10.0 {
            score -= 12.0;
        } else if gap > 0.0 && gap < ni && gap < 10.0 {
            // this placement creates a gap the next item cannot use
            score += 10.0;
        }
    }

    // Slight preference for bins already below mean residual (balancing).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // prefer small leftover after hypothetical next placement
            let two_step_left = post_residual - next_item_size;
            score -= 60.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            if two_step_left <= 5 {
                score -= 120.0;
            }
        } else {
            // next item cannot follow: penalize proportionally to wasted potential
            score += 40.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 250.0 * (open_bins_count as f64).max(1.0);
        // allow new bin if item is huge and would leave awkward remainder
        if item_size > 70 && post_residual < 10 {
            score -= 400.0;
        }
    }

    // Slight late-stream bias toward consolidating into fewest bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        // small gaps are dangerous dead space after next item
        if gap > 0.0 && gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap > 0.0 && gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        // gap large enough to hold next item again is good
        if gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.5;
            }
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
            score -= 0.8;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasted space
        let dead = post_residual as f64;
        score += 3.2 + 0.02 * dead;
        if dead > 0.0 {
            score += 42.0 * (1.0 - dead / cap_f);
        }
        if post_residual < next_item_size / 2 {
            score += 2.5;
        }
        if post_residual > 0 && post_residual < bin_capacity / 12 {
            score += 2.2;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score += 1.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 600.0;
    }

    // Fragmentation relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // fresh bin attractive when open bins are fragmented
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        // big item now, next item big too: fresh bin may serve both
        if next_item_size > 0 && next_item_size <= post_residual && item_size as f64 >= 0.5 * cap_f {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        let waste_risk = if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 6.0 };
        score += waste_risk + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
    }

    // Mild consolidation pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny dead space
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
