    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize large dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fit bonus
    }
    if post_residual > 50 {
        score += 15.0; // wasteful half-empty bin
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit is bad.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 35.0;
        // discount when many open bins are already tight (little room left)
        let avg_room = mean_residual;
        if avg_room < item_size as f64 * 1.2 {
            score -= 30.0;
