        // as stream progresses, prefer consolidating into existing bins less
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // if item is large relative to mean residual, new bin more appealing
        if (item_size as f64) > avg_room {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 && !is_new_bin {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
