                score += slack as f64 * 0.05;
            }
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            score += next * 0.10;
        }
    }

    // Last chance: strongly prefer using the only fitting bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline adjusted by context
    if bin_residual == bin_capacity {
