        if fitting_bins_count <= 1 {
            score += 20.0; // don't open new bin when an existing bin is a last chance
        }
    }

    // Slight global pressure to consolidate as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

