        score += waste_risk + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items (more bins to work with later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // Next item can chain-fill this residual twice: extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // Fine-grained residual compaction: reward residuals that are small but still usable
    // by the next item, coupling tightness with lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let missing = (next_item_size - post_residual) as f64;
        score += 1.5 * (1.0 - missing / cap_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residuals that cannot fit typical items are waste.
    // Penalize gaps that are non-zero but too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits strongly: residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 150.0;
    } else {
        // Fractional dead-space ratio penalty (non-linear).
        let dead_ratio = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead_ratio * dead_ratio;
    }

    // If the next item fits exactly into the post_residual, reward heavily (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: mild penalty unless it's near zero.
        if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = open_bins_count as f64;
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // leftover bin; prefer placing items into above-mean-residual bins when many bins open.
    let this_residual = post_residual as f64;
    if open_bins_count > 2 {
        score += 0.3 * (mean_residual - this_residual);
    }

    // Progress-based scaling: late in the stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fit (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when the leftover space exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        }
        // Penalize leaving a gap that is uselessly close to but smaller than next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    }

    // Prefer filling bins that are already below-average residual (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate: fewer open bins relative to stream length.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling: heavily penalize opening a new bin when other
    // open bins can also fit the item; allow it when it is the only option.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 1 {
            score += 800.0;
        } else {
            // Only candidate: opening a fresh bin is fine, small bonus so it wins.
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / cap_f);
            // small gaps are dangerous dead space after next item
            if gap > 0.0 && gap < 8.0 {
                score -= 2.2 * (1.0 - gap / 8.0);
            }
            if gap > 0.0 && gap < 4.0 {
                score -= 1.0 * (1.0 - gap / 4.0);
