        score -= 0.1 * (pr - mean_residual);
    }

    // Fill-level shaping: prefer fuller bins
    score -= 80.0 * (1.0 - pr / cap_f);

    // Last-chance bin: favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if fitting_bins_count == 0 {
