        // big item now, next item big too: fresh bin may serve both
        if next_item_size > 0 && next_item_size <= post_residual && item_size as f64 >= 0.5 * cap_f {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            let slack = pr / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
        score += 0.5 * open_bins_count as f64;
    }

    // Mild consolidation pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny dead space
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
