pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) - pr_norm * (0.3 + 1.5 * progress);
    score += 20.0 * poly;

    // Penalize dead space more as stream progresses (waste compounds)
    score += 3.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits
    score -= 5.0 * (1.0 - pr_norm).powi(3);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            score += 3.0;
        }
    }

    // Slight preference to spread load when many bins are open
    score += 0.05 * (pr - mean_residual).abs();

    // Mild bias against opening new bins early
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space buckets.
    // Small post_residual = tight fit -> strong reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fill
    } else if pr <= 10 {
        score -= 90.0;
    } else if pr <= 20 {
        score -= 40.0;
    } else if pr <= 30 {
        score -= 15.0;
    } else if pr <= 50 {
        score += 10.0; // half-empty bin, wasteful
    } else {
        score += 25.0; // mostly empty, prefer new bin instead
    }

    // Dead space that the next item cannot use: penalize hard.
    if next_item_size > 0 {
        if next_item_size > pr {
            // this bin becomes unusable for the next item
            score += 0.5 * (pr as f64);
            // if next item fits item_size exactly, mild forgiveness
            if next_item_size <= item_size + pr && next_item_size >= pr {
                score -= 5.0;
            }
        } else {
            // next item can use the leftover: reward proportionally
            let fill_next = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * fill_next;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with better (smaller) post_residual, already reflected
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Harmonic capacity fractions: penalize leaving residuals at awkward
    // modular classes (e.g. residual mod 10 large means hard-to-fill gap).
    let m = pr % 10;
    score += 2.0 * m as f64;

    // Prefer filling bins that are already relatively full.
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * used_frac;

    // Prefer denser packing across the fleet: if this bin's residual is
    // below the mean residual, it is a good consolidation target.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more willing to open bins (future flexibility);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress);

    // Brand-new bin candidate: neutral base plus a bias so it is chosen
    // only when open bins score badly (large post_residual / dead space).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size > 50 {
            score -= 10.0; // big next item: fresh bin is valuable
        }
    }

    score
}

