        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
        // NEW: when only one bin fits and the next item is small, opening a fresh
        // bin preserves the existing residual for the (smaller) next item.
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size < item_size && post_residual >= next_item_size {
            score -= 3.0;
        }
        // NEW: penalize opening bins late in the stream when capacity is ample elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && open_bins_count > 3 && fitting_bins_count >= 2 {
            score += 3.0;
        }
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // Next item can chain-fill this residual twice: extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // NEW: combine residual tightness with lookahead — bins whose post-residual
    // is a near-exact multiple of the next item size are prime chain candidates.
    if next_item_size > 0 && post_residual > 0 {
        let m = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if m >= 1 && rem <= 2 {
            score -= 1.2 * m as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    // A gap is "dead" if it's too small for typical future items (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates a gap the next item cannot use
    }

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // but allow it when existing residuals are all small (dead-space pressure).
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0; // existing bins are mostly dead space anyway
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for tighter fits among comparable residuals.
    score -= (item_size as f64 / bin_residual as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;

        // Perfect lookahead match: strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        }

        // Penalize residual too small for any future item (dead space, min item = 1)
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless open bins are truly fragmented
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // room for a perfect pair in a fresh bin
            score -= 35.0;
        }
    }

    // Slight preference for tight fits overall
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 * (1.0 - tightness.min(1.0));
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that nothing typical can use (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + next_item_size as f64 * 0.1;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Penalize creating residual that blocks the next item.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Prefer filling existing bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }
    if item_size == bin_residual {
        score -= 10.5;
    } else if item_size >= bin_residual {
        score -= 2.0;
    }

    // 2-step lookahead: reward when next item fits the new residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / cap_f);
        if gap == 0.0 {
            score -= 7.0;
        }
        if gap < 8.0 {
            score -= 2.2 * (1.0 - gap / 8.0);
        }
        if gap < 4.0 {
            score -= 1.0 * (1.0 - gap / 4.0);
        }
        if gap >= next_item_size as f64 {
            score -= 2.5;
            if fitting_bins_count <= 2 {
                score -= 1.5;
            }
        }
        if (gap as u32) >= 2 * next_item_size {
            score -= 1.8;
        }
        if (gap as u32) >= 3 * next_item_size {
            score += 1.0;
        }
        if (gap as u32) < mean_residual as u32 {
            score -= 2.0;
        }
        if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
            score -= 0.8;
        }
        if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
            score += 1.2;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 3.2 + 0.02 * dead;
            score += 42.0 * (1.0 - dead / cap_f);
            if dead < 20.0 {
                score += 2.0;
            }
            if post_residual < bin_capacity / 12 {
                score += 2.2;
            }
            if (post_residual as f64) < mean_residual * 0.6 {
                score += 1.0;
            }
            score += (next_item_size - post_residual) as f64 * 0.05;
            if post_residual >= next_item_size / 2 && post_residual < next_item_size && next_item_size > bin_capacity / 3 {
                score += 1.0;
            }
            if post_residual >= next_item_size / 2 && next_item_size <= bin_capacity / 2 {
                score -= 1.5;
            }
        }
    }

    // Tight fit reward: less waste relative to capacity.
    score -= 80.0 * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 200.0;
        score -= 60.0 * (fragmentation / cap_f);
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 250.0;
        }
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count <= 1 {
            score -= 1.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.6 * cap_f && fitting_bins_count >= 2 {
            score += 0.8;
        }
        if next_item_size > 0 && item_size + 12 <= bin_residual && item_size + 12 < next_item_size {
            score -= 2.2;
        }
        if fitting_bins_count > 0 {
            let slack = (post_residual as f64) / cap_f;
            if slack > 0.5 {
                score += 40.0;
            }
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 1.5;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size < item_size && post_residual >= next_item_size {
            score -= 3.0;
        }
        // Borrowed: waste-risk term — discourage opening bins when next item
        // itself cannot fit a fresh bin's capacity profile is impossible here,
        // so instead penalize by open-bin count to curb bin proliferation.
        let waste_risk = if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 6.0 };
        score += waste_risk + 0.5 * open_bins_count as f64;
        // Late-stream pressure: penalize opening bins when capacity is ample elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && open_bins_count > 3 && fitting_bins_count >= 2 {
            score += 3.0;
        }
    }

    // Mild penalty for deviating from mean residual: prefer balanced packing.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    // Next item can chain-fill this residual twice: extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && fitting_bins_count >= 3 {
        score -= 0.8;
    }

    // Chain candidates: post-residual a near-exact multiple of next item size.
    if next_item_size > 0 && post_residual > 0 {
        let m = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if m >= 1 && rem <= 2 {
            score -= 1.2 * m as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Reward tight fits: normalized fill fraction, non-linear in progress.
    let fill = 1.0 - post / cap;
    score -= fill * fill * (20.0 + 30.0 * progress);

    // Penalize small dead space that nothing (>=1) can use later: smooth quadratic.
    let dead = if post > 0.0 { post } else { 0.0 };
    let smallness = (1.0 - dead / cap).max(0.0);
    score += smallness * smallness * 15.0 * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack) * 18.0 * (1.0 - progress);
        } else {
            score += (nxt - post) / cap * 10.0;
        }
    }

    // New-bin candidate: penalize mildly early, allow late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 - 25.0 * progress * fragmentation;
    }

    // Mild preference for bins below mean residual (concentrate large leftovers).
    score += ((post - mean_residual) / cap) * 6.0 * (1.0 - progress);

    // Smooth polynomial coupling of post_residual with progress.
    let x = post / cap;
    score += x * x * (1.0 - x) * 12.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / cap_f);
            // small gaps are dangerous dead space after next item
            if gap > 0.0 && gap < 8.0 {
                score -= 2.5 * (1.0 - gap / 8.0);
            }
            if gap > 0.0 && gap < 4.0 {
                score -= 1.2 * (1.0 - gap / 4.0);
            }
            // gap large enough to hold next item again is good
            if gap as u32 >= next_item_size {
                score -= 3.0;
                if fitting_bins_count <= 2 {
                    score -= 1.5;
                }
            }
            // gap holding next item twice is even better; thrice slightly worse (over-reserve)
            if (gap as u32) >= 2 * next_item_size {
                score -= 1.8;
            }
            if (gap as u32) >= 3 * next_item_size {
                score += 1.0;
            }
            // gap just under next item: nearly-useless sliver
            if gap > 0.0 && gap < next_item_size as f64 && gap > (bin_capacity / 20) as f64 {
                score += 1.2;
            }
            if gap > 0.0 && gap < (next_item_size as f64) * 0.5 {
                score -= 0.8;
            }
        } else {
            // next item won't fit here; penalize wasted space
            let dead = post_residual as f64;
            score += 0.5 * (next_item_size as f64 - dead);
            score += 42.0 * (1.0 - dead / cap_f);
            if post_residual > 0 && post_residual < bin_capacity / 12 {
                score += 2.2;
            }
            if post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
                score += 1.0;
            }
            if post_residual >= next_item_size / 2 && next_item_size > bin_capacity / 3 {
                score += 1.0;
            }
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 600.0;
    }

    // Fragmentation relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 200.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // fresh bin attractive when open bins are fragmented
        if open_bins_count > 4 && mean_residual < item_size as f64 * 1.2 {
            score -= 260.0;
        }
        // big item now, next item fits after it: fresh bin may serve both
        if next_item_size > 0 && next_item_size <= post_residual && item_size as f64 >= 0.5 * cap_f {
            score -= 40.0;
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 2.0;
        }
        // avoid opening fresh bins when a roomy fit already exists
        if fitting_bins_count > 0 && pr > 0.5 * cap_f {
            score += 40.0;
        }
        score += 0.5 * open_bins_count as f64;
    }

    // Mild consolidation pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress;

    // Penalize tiny dead space
    if pr > 0.0 && pr < 10.0 {
        score += 200.0;
    }

    score
}
